package io.tenvyr.control.engine;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import io.tenvyr.platform.*;
import io.tenvyr.control.authority.*;
import java.net.URI;
import java.sql.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

/** Real PostgreSQL parity cases. A private schema isolates the fixtures without replacing JDBC. */
public final class EngineIntegrationCheck {
    private static int checks;
    private static void check(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
    private static ObjectNode result(ExecutionService.Claim claim,JsonNode output){return Json.object("schemaVersion","1","invocationId",claim.attempt().get("invocationId"),"executionId",claim.attempt().get("executionId"),"stepExecutionId",claim.logicalStep().get("id"),"status","succeeded","output",output,"completedAt",Protocol.jsInstant(Instant.now()));}
    private static ObjectNode source(String delivery){return Json.object("adapter","http","keyId","test","deliveryId",delivery,"receivedAt",Protocol.jsInstant(Instant.now()));}
    private static ExecutionService.Claim claim(ExecutionService executions,ObjectNode execution,ObjectNode step){executions.reconcileExecution(Json.text(execution,"id"));ExecutionService.Claim claimed=executions.claimRunnableStep(Json.text(execution,"id"),step,Json.object(),Json.integer(step,"retries",0)+1,null);if(claimed==null)throw new AssertionError("Expected a claim");return claimed;}
    public static void main(String[] args)throws Exception{
        if(!Arrays.asList(args).contains("--integration"))throw new IllegalArgumentException("EngineIntegrationCheck requires --integration");
        String raw=System.getenv("TEST_DATABASE_URL");if(raw==null)raw=System.getenv("TENVYR_TEST_DATABASE_URL");if(raw==null)throw new IllegalArgumentException("TEST_DATABASE_URL is required for real PostgreSQL integration checks");
        String user=System.getenv().getOrDefault("POSTGRES_USER","postgres"),password=System.getenv().getOrDefault("POSTGRES_PASSWORD","postgres"),url;
        if(raw.startsWith("jdbc:postgresql:"))url=raw;else{URI parsed=URI.create(raw);if(!Set.of("postgres","postgresql").contains(parsed.getScheme()))throw new IllegalArgumentException("PostgreSQL test URL required");if(parsed.getRawUserInfo()!=null){String[] auth=parsed.getUserInfo().split(":",2);user=auth[0];password=auth.length>1?auth[1]:"";}url="jdbc:postgresql://"+parsed.getHost()+":"+(parsed.getPort()<0?5432:parsed.getPort())+parsed.getPath();}
        URI parsed=URI.create(url.substring(5));String database=parsed.getPath();if(database==null||!database.toLowerCase(Locale.ROOT).matches(".*(?:test|scratch|disposable).*"))throw new IllegalArgumentException("Integration target database name must contain test, scratch, or disposable");
        String schema="engine_check_"+UUID.randomUUID().toString().replace("-","");Db admin=new Db(url,user,password);admin.execute("CREATE SCHEMA "+Db.identifier(schema));
        Db db=new Db(url+(url.contains("?")?"&":"?")+"currentSchema="+schema+",public",user,password);
        try{Migrator.migrate(db);AtomicReference<String> policyConfig=new AtomicReference<>();AuthorityServices authority=new AuthorityServices(db,policyConfig::get);Conditions conditions=new Conditions();PipelineService pipelines=new PipelineService(db,authority,conditions);AgentTransportConfig transport=new AgentTransportConfig(Map.of());
            AtomicBoolean completionHeld=new AtomicBoolean();AtomicInteger heldChecks=new AtomicInteger();
            EngineRuntime runtime=new EngineRuntime(){public ObjectNode resolveExecutor(Connection c,ObjectNode step,ObjectNode descriptor){return transport.frozenDescriptor(descriptor);}public JsonNode workspaceMetadata(Connection c,String id){return null;}public boolean reconcileCoordination(String id){return false;}public boolean completionHeld(String id){if(completionHeld.get())heldChecks.incrementAndGet();return completionHeld.get();}public boolean isVerifierStep(String id,String step){return false;}public JsonNode buildVerifierInput(String id,String step){throw new AssertionError("This fixture has no verifier");}};
            ExecutionService executions=new ExecutionService(db,authority,runtime,transport,conditions);authority.bind(pipelines,executions,runtime,transport);ResultInboxService inbox=new ResultInboxService(db,authority);AgentEventService events=new AgentEventService(db);
            ObjectNode one=Json.object("id","one","agent","reader");ObjectNode pipeline=pipelines.create(Json.object("name","claim-race","version","1","steps",Json.array(one)));ObjectNode execution=executions.createExecution(pipeline,Json.object("captured","input"));executions.reconcileExecution(Json.text(execution,"id"));
            ExecutorService workers=java.util.concurrent.Executors.newFixedThreadPool(8);List<Callable<ExecutionService.Claim>> calls=new ArrayList<>();for(int i=0;i<16;i++)calls.add(()->executions.claimRunnableStep(Json.text(execution,"id"),one,Json.object(),1,null));int won=0;ExecutionService.Claim winner=null;try{for(Future<ExecutionService.Claim> call:workers.invokeAll(calls)){ExecutionService.Claim value=call.get();if(value!=null){won++;winner=value;}}}finally{workers.shutdownNow();}check(won==1,"one concurrent durable claim wins");check(executions.getStepAttempts(Json.text(winner.logicalStep(),"id")).size()==1,"one immutable attempt");check(db.one("SELECT COUNT(*) n FROM dispatch_outbox WHERE \"stepAttemptId\"=?::uuid",winner.attempt().get("id")).path("n").asInt()==1,"one durable outbox handoff");
            ObjectNode success=result(winner,Json.object("ok",true));check(inbox.apply(success,source("first")).disposition().equals("applied"),"result transaction applied");check(inbox.apply(success,source("again")).disposition().equals("duplicate"),"semantic redelivery idempotent");ObjectNode conflict=success.deepCopy();conflict.set("output",Json.object("ok",false));check(inbox.apply(conflict,source("conflict")).disposition().equals("conflict"),"different canonical payload retained as conflict");check(db.one("SELECT COUNT(*) n FROM result_conflicts WHERE \"invocationId\"=?",winner.attempt().get("invocationId")).path("n").asInt()==1,"durable conflict evidence");
            executions.cancelExecution(Json.text(execution,"id"),"test terminal");ObjectNode cap=authority.capsules.build(Json.text(execution,"id"));check(cap.path("header").path("attemptCount").asInt()==1&&cap.path("header").path("inboxCount").asInt()==1,"capsule exact durable counts");check(cap.path("attempts").path(0).path("stepId").asText().equals("one"),"capsule stable DAG identity");ObjectNode cap2=authority.capsules.build(Json.text(execution,"id"));check(cap.get("contentHash").equals(cap2.get("contentHash")),"repeatable-read capsule stable identity");ObjectNode export=authority.capsules.createExport(Json.text(execution,"id"),"operator",null);check(export.get("id").equals(authority.capsules.createExport(Json.text(execution,"id"),"operator","again").get("id")),"export hash pin idempotent");
            db.update("pipelines",Json.text(pipeline,"id"),Json.object("steps",Json.array(Json.object("id","mutated","agent","different"))));ObjectNode replay=authority.capsules.replay(Json.text(execution,"id"),"operator",null);ObjectNode target=executions.getExecution(Json.text(replay,"targetExecutionId"));check(executions.getExecutionPlanSteps(target).path(0).path("id").asText().equals("one"),"replay captured plan despite pipeline mutation");check(target.get("input").equals(execution.get("input")),"replay captured input");check(authority.capsules.replay(Json.text(execution,"id"),"operator",null).get("targetExecutionId").equals(target.get("id")),"replay idempotent target");check(executions.getStepAttempts(Json.text(executions.getStepExecutions(Json.text(target,"id")).get(0),"id")).isEmpty(),"replay never copies historical attempts");

            ObjectNode produce=Json.object("id","produce","agent","reader","stateWrites",Json.array(Json.object("key","answer","fromOutput","/answer"))),consume=Json.object("id","consume","agent","writer","dependsOn",Json.array("produce"),"contextProjection",Json.object("stateKeys",Json.array("answer"),"artifacts",Json.array(Json.object("fromStep","produce","ordinal",0))));ObjectNode statePipeline=pipelines.create(Json.object("name","state-artifacts","version","1","steps",Json.array(produce,consume)));ObjectNode stateExecution=executions.createExecution(statePipeline,Json.object());ExecutionService.Claim producer=claim(executions,stateExecution,produce);ObjectNode producerResult=result(producer,Json.object("answer",Json.object("value",42)));producerResult.set("artifacts",Json.array(Json.object("uri","file:///tmp/evidence.txt","name","evidence","mediaType","text/plain")));check(inbox.apply(producerResult,source("producer")).disposition().equals("applied"),"state/artifact result applied");ObjectNode state=authority.state.read(Json.text(stateExecution,"id"));check(state.path("version").intValue()==1&&state.path("state").path("answer").path("value").intValue()==42,"controlled state version exactly once");inbox.apply(producerResult,source("producer-again"));check(authority.state.read(Json.text(stateExecution,"id")).path("version").intValue()==1,"duplicate never rewrites state");ExecutionService.Claim consumer=claim(executions,stateExecution,consume);check(consumer.attempt().path("contextSnapshot").path("tenvyr").path("artifacts").size()==1,"claim resolves canonical artifact identity");check(executions.countArtifactExposures(Json.text(stateExecution,"id"))==1,"claim exposure committed");
            ObjectNode event=Json.object("schemaVersion","1","eventId","event","invocationId",consumer.attempt().get("invocationId"),"executionId",stateExecution.get("id"),"stepExecutionId",consumer.logicalStep().get("id"),"sequence",1,"type","progress","payload",Json.object("percent",10),"trace",Json.object("traceId",stateExecution.get("id"),"correlationId",consumer.attempt().get("invocationId")),"occurredAt",Protocol.jsInstant(Instant.now()));check(events.apply(event,source("event")).equals("applied"),"durable operational event");check(events.apply(event,source("event-again")).equals("duplicate"),"event identity idempotent");ObjectNode alternate=event.deepCopy();alternate.put("eventId","different");check(events.apply(alternate,source("event-conflict")).equals("conflict"),"event sequence owner conflict");

            ObjectNode account=authority.budget.createAccount(Json.object("scopeType","operator","scopeId",schema,"ceilings",Json.object("tokens",100)),null);ObjectNode child=authority.budget.createAccount(Json.object("scopeType","child","scopeId",schema,"parentAccountId",account.get("id"),"ceilings",Json.object("tokens",80)),null);ObjectNode reservation=authority.budget.reserve(Json.object("accountId",child.get("id"),"dimension","tokens","amount",40,"idempotencyKey",schema+":reservation"),null);check(authority.budget.projection(Json.text(account,"id")).path("available").path("tokens").longValue()==60,"child reserve debits ancestor");authority.budget.commit(Json.object("reservationId",reservation.get("id"),"amount",15),null);authority.budget.release(Json.object("reservationId",reservation.get("id"),"amount",25),null);check(authority.budget.projection(Json.text(account,"id")).path("available").path("tokens").longValue()==85,"unused child release credits ancestor");
            policyConfig.set(Json.stringify(Json.object("version",1,"rules",Json.array(Json.object("id","human","actionType","dispatch","effect","REQUIRE_APPROVAL")))));ObjectNode approvalPipeline=pipelines.create(Json.object("name","approval","version","1","steps",Json.array(one)));ObjectNode waitingExecution=executions.createExecution(approvalPipeline,Json.object());ExecutionService.Claim waiting=claim(executions,waitingExecution,one);check(waiting.disposition().equals("approval_required"),"policy parks same attempt");check(db.one("SELECT COUNT(*) n FROM dispatch_outbox WHERE \"stepAttemptId\"=?::uuid",waiting.attempt().get("id")).path("n").intValue()==0,"approval parks without dispatch");authority.approvals.approve(Json.text(waiting.attempt(),"invocationId"),null,null);check(executions.getAttemptByInvocationId(Json.text(waiting.attempt(),"invocationId")).path("status").asText().equals("CREATED"),"approval resumes same attempt");authority.approvals.approve(Json.text(waiting.attempt(),"invocationId"),null,null);check(executions.getStepAttempts(Json.text(waiting.logicalStep(),"id")).size()==1,"approval replay never creates attempt");check(db.one("SELECT COUNT(*) n FROM dispatch_outbox WHERE \"stepAttemptId\"=?::uuid",waiting.attempt().get("id")).path("n").intValue()==1,"approval creates one atomic outbox");
            policyConfig.set(null);ObjectNode delegation=authority.delegation.request(Json.object("parentExecutionId",waitingExecution.get("id"),"parentAttemptId",waiting.attempt().get("id"),"requestId","child","requestedAgent","writer","expiresAt",Instant.now().plusSeconds(60).toString()));check(delegation.path("disposition").asText().equals("created"),"delegation durable request");ObjectNode childPipeline=pipelines.create(Json.object("name","delegated-child","version","1","steps",Json.array(one)));ObjectNode approved=authority.delegation.approve(Json.text(waiting.attempt(),"id"),"child",childPipeline);check(approved.path("decision").asText().equals("APPROVED"),"explicit approval creates child: "+approved);check(authority.delegation.approve(Json.text(waiting.attempt(),"id"),"child",childPipeline).get("childExecutionId").equals(approved.get("childExecutionId")),"child approval idempotent");executions.cancelExecution(Json.text(waitingExecution,"id"),"parent cancelled");check(authority.delegation.cancelOrphans(20)==1,"durable orphan cancellation");check(executions.getExecution(Json.text(approved,"childExecutionId")).path("status").asText().equals("CANCELLED"),"cancel cascades to child");
            ObjectNode heldPipeline=pipelines.create(Json.object("name","completion-hold","version","1","steps",Json.array(one)));
            ObjectNode heldExecution=executions.createExecution(heldPipeline,Json.object());ExecutionService.Claim heldAttempt=claim(executions,heldExecution,one);inbox.apply(result(heldAttempt,Json.object("done",true)),source("held-result"));
            completionHeld.set(true);EngineService engine=new EngineService(pipelines,executions,inbox,events,null,runtime,ignored->{});
            engine.reconcileExecution(Json.text(heldExecution,"id"));
            check(heldChecks.get()>0&&heldChecks.get()<=2,"completion hold is quiescent instead of reporting false progress for 100 passes");
            check(executions.getExecution(Json.text(heldExecution,"id")).path("status").asText().equals("RUNNING"),"completion hold preserves execution authority");
            completionHeld.set(false);engine.reconcileExecution(Json.text(heldExecution,"id"));
            check(executions.getExecution(Json.text(heldExecution,"id")).path("status").asText().equals("COMPLETED"),"releasing the hold permits normal completion");
            System.out.println("EngineIntegrationCheck: "+checks+" real PostgreSQL checks passed");
        }finally{admin.execute("DROP SCHEMA "+Db.identifier(schema)+" CASCADE");}
    }
}
